-- Migration 006 — payments subsystem: deposits, payment_runs, payment_transactions (spec B8.5/B8.6)
-- From DEPOSITS & OTHER, PAYMENTS_MASTER, PAYMENTS_TRANSACTIONS.
--   deposits             = deposit/"other" pool + drawdown (linked POs), B8.6
--   payment_runs         = supplier-agnostic payment runs (date/bank/currency rollup), B8.5
--   payment_transactions = the register: each estimate->actual txn, linked to a deposit or PO milestone
-- Multi-value cells (comma lists of POs/suppliers) are kept as raw text for now; normalise later.
-- HOW TO APPLY: tested on sandbox; BEN runs on live.

create table if not exists planner.deposits (
  reference           text primary key,      -- PO_or_deposit_reference e.g. "P55-UK-XR1"
  supplier_name       text,
  supplier_id         bigint references planner.suppliers(id),
  prod_no             text,
  country             text,
  description         text,
  is_deposit          boolean not null default false,   -- 'checked' -> true
  amount              numeric(14,2),
  date_due            date,
  date_likely_pay     date,
  estimated_pay_date  date,
  date_paid           date,
  date_paid_link      date,
  xero_fx             numeric(12,5),
  deposit_used        numeric(14,2),
  deposit_remaining   numeric(14,2),
  production_contract text,
  linked_pos          text,                  -- raw comma list of POs drawing on this deposit
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

create table if not exists planner.payment_runs (
  id                bigint generated always as identity primary key,
  invoice_reference text,                    -- e.g. SUPPLIER-PAYMENT-2026-02-27 (not guaranteed unique)
  payment_date      date,
  supplier_name     text,
  paid_from         text,                    -- bank
  total_payment     numeric(14,2),
  usd_amount        numeric(14,2),
  gbp_amount        numeric(14,2),
  eur_amount        numeric(14,2),
  notes             text,
  created_at        timestamptz not null default now()
);

create table if not exists planner.payment_transactions (
  id                    bigint generated always as identity primary key,
  payment_date          date,
  payment_run_ref       text,                -- payments_master_LINK
  transaction_reference text,                -- e.g. "P55-UK-WK1" (may be comma list)
  transaction_type      text,                -- Deposit / Completion / Balance / Tax
  transaction_amount    numeric(14,2),
  transaction_supplier  text,
  invoice_reference     text,
  deposit_ref           text,                -- -> deposits.reference (DEPOSITS & OTHER link)
  po_completion         text,                -- PO:completion_payment
  po_balance_1          text,
  po_balance_2          text,
  po_balance_3          text,
  created_at            timestamptz not null default now()
);

create index if not exists deposits_supplier_idx     on planner.deposits(supplier_id);
create index if not exists pay_txn_type_idx           on planner.payment_transactions(transaction_type);
create index if not exists pay_txn_deposit_idx        on planner.payment_transactions(deposit_ref);

comment on table planner.deposits is 'Deposit/other pool + drawdown (DEPOSITS & OTHER) — spec B8.6.';
comment on table planner.payment_runs is 'Supplier-agnostic payment runs (PAYMENTS_MASTER) — spec B8.5.';
comment on table planner.payment_transactions is 'Payment register, txn-level (PAYMENTS_TRANSACTIONS) — spec B8.5.';

